<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$students=$pdo->query("SELECT s.*,u.full_name teacher_name,EXISTS(SELECT 1 FROM parent_student_links l WHERE l.student_id=s.id AND l.status='active') has_parent FROM students s LEFT JOIN users u ON u.id=s.teacher_id ORDER BY s.kelas,s.nama_lengkap")->fetchAll();$editing=null;if(!empty($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM students WHERE id=?');$stmt->execute([$_GET['edit']]);$editing=$stmt->fetch()?:null;}$pageTitle='Daftar Siswa';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Data Peserta Didik</p><h1 class="page-title">Daftar Siswa Lengkap</h1><p class="page-description">Tambah, ubah, hapus, cari, dan impor biodata siswa dari Excel sekolah.</p></div><div class="actions"><button class="btn btn-soft" data-modal-open="import-students">⇩ Impor Excel</button><button class="btn btn-primary" data-modal-open="student-form">+ Tambah Siswa</button></div></div><section class="card"><div class="filter-row"><input class="input" data-search-table="#student-list" placeholder="Cari nama, NIS, kelas, atau level..."><span class="badge badge-blue"><?= count($students) ?> Siswa</span></div><div class="table-wrap"><table class="table" id="student-list"><thead><tr><th>Siswa</th><th>Kelas</th><th>Level</th><th>Jenis Kelamin</th><th>Orang Tua</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($students as $student):?><tr><td class="name"><?= e($student['nama_lengkap']) ?><br><small class="muted">NIS <?= e($student['nis']) ?></small></td><td><span class="badge badge-blue"><?= e($student['kelas']) ?></span></td><td><?= e(level_name($student['level'])) ?></td><td><?= e($student['jenis_kelamin']?:'-') ?></td><td><span class="badge <?= $student['has_parent']?'badge-green':'badge-yellow' ?>"><?= $student['has_parent']?'Terhubung':'Belum ada' ?></span></td><td><?= e(str_replace('_',' ',$student['status'])) ?></td><td><div class="actions"><a class="btn btn-blue btn-sm" href="<?= url('guru/students.php?edit='.$student['id']) ?>">Edit</a><form action="<?= url('api/students/index.php') ?>" method="post" data-ajax><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="student_id" value="<?= e($student['id']) ?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus siswa beserta seluruh nilai dan laporan?">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="7"><div class="empty"><strong>Belum ada siswa</strong>Tambahkan satu per satu atau impor file XLSX.</div></td></tr><?php endif;?></tbody></table></div></section>
<div class="modal <?= $editing?'open':'' ?>" id="student-form"><div class="modal-card"><div class="modal-head"><div><p class="eyebrow">Biodata Siswa</p><h2><?= $editing?'Edit Siswa':'Tambah Siswa Baru' ?></h2></div><button class="modal-close" data-modal-close>×</button></div><form action="<?= url('api/students/index.php') ?>" method="post" data-ajax class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $editing?'update':'create' ?>"><input type="hidden" name="student_id" value="<?= e($editing['id']??'') ?>"><div class="field full"><label>Nama Lengkap</label><input class="input" name="nama_lengkap" required value="<?= e($editing['nama_lengkap']??'') ?>"></div><div class="field"><label>NIS</label><input class="input" name="nis" required value="<?= e($editing['nis']??'') ?>"></div><div class="field"><label>Kelas</label><select class="select" name="kelas"><?php foreach(all_class_names() as $class):?><option <?= ($editing['kelas']??'1A')===$class?'selected':'' ?>><?= $class ?></option><?php endforeach;?></select></div><div class="field"><label>Level Tahfidz</label><select class="select" name="level"><?php for($level=1;$level<=9;$level++):?><option value="<?= $level ?>" <?= (int)($editing['level']??1)===$level?'selected':'' ?>><?= e(level_name($level)) ?></option><?php endfor;?></select></div><div class="field"><label>Jenis Kelamin</label><select class="select" name="jenis_kelamin"><option value="">-</option><option value="L" <?= ($editing['jenis_kelamin']??'')==='L'?'selected':'' ?>>Laki-laki</option><option value="P" <?= ($editing['jenis_kelamin']??'')==='P'?'selected':'' ?>>Perempuan</option></select></div><div class="field"><label>NIK (16 digit)</label><input class="input" name="nik" pattern="[0-9]{16}" value="<?= e($editing['nik']??'') ?>"></div><div class="field"><label>Tempat/Tanggal Lahir</label><input class="input" name="tempat_tanggal_lahir" value="<?= e($editing['tempat_tanggal_lahir']??'') ?>"></div><div class="field"><label>Nama Ayah</label><input class="input" name="nama_ayah" value="<?= e($editing['nama_ayah']??'') ?>"></div><div class="field"><label>Nama Ibu</label><input class="input" name="nama_ibu" value="<?= e($editing['nama_ibu']??'') ?>"></div><div class="field"><label>Wali Murid</label><input class="input" name="wali_murid" value="<?= e($editing['wali_murid']??'') ?>"></div><div class="field"><label>No. Telepon</label><input class="input" name="no_telp" value="<?= e($editing['no_telp']??'') ?>"></div><div class="field full"><label>Alamat</label><textarea class="textarea" name="alamat"><?= e($editing['alamat']??'') ?></textarea></div><button class="btn btn-primary field full">Simpan Data Siswa</button></form></div></div>
<div class="modal" id="import-students"><div class="modal-card"><div class="modal-head"><div><p class="eyebrow">Impor Data</p><h2>Impor Excel Siswa</h2></div><button class="modal-close" data-modal-close>×</button></div><div class="alert alert-info">Sistem mendeteksi kolom NIS dan Nama Peserta Didik secara otomatis. Format XLSX dan CSV didukung.</div><form action="<?= url('api/import/students.php') ?>" method="post" enctype="multipart/form-data" data-ajax class="form-grid"><?= csrf_field() ?><div class="field full"><label>File Excel</label><input class="input" type="file" name="file" accept=".xlsx,.csv" required></div><div class="field"><label>Kelas Default</label><select class="select" name="kelas"><?php foreach(all_class_names() as $class):?><option><?= $class ?></option><?php endforeach;?></select></div><div class="field"><label>Level Default</label><select class="select" name="level"><?php for($level=1;$level<=9;$level++):?><option value="<?= $level ?>"><?= e(level_name($level)) ?></option><?php endfor;?></select></div><button class="btn btn-primary field full">Impor dan Sinkronkan Berdasarkan NIS</button></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>

